    26→export async function userDocumentExists(userId: string): Promise<boolean> {
    27→  try {
    28→    const userRef = doc(db, 'users', userId);
    29→    const userSnap: DocumentSnapshot = await getDoc(userRef);
    30→    return userSnap.exists();
