    37→/**
    38→ * Creates a new user document in Firestore
    39→ * @param userId - The user ID
    40→ * @param userData - The user data to save
    41→ */
    42→export async function createUserDocument(
    43→  userId: string,
    44→  userData: Partial<UserDocument>,
    45→): Promise<void> {
    46→  try {
    47→    const userRef = doc(db, 'users', userId);
    48→    const timestamp = Date.now();
    49→
    50→    await setDoc(userRef, {
    51→      uid: userId,
    52→      createdAt: timestamp,
    53→      updatedAt: timestamp,
    54→      ...Object.fromEntries(Object.entries(userData).filter(([_, v]) => v)),
    55→    });
    56→
    57→    console.log('User document created:', userId);
    58→  } catch (error) {
    59→    console.error('Error creating user document:', error);
    60→    throw error;
    61→  }
    62→}
