     1→import {
     2→  collection,
     3→  getDocs,
     4→  orderBy,
     5→  query,
     6→  QuerySnapshot,
     7→  where,
     8→} from 'firebase/firestore';
     9→import { db } from './config';
    10→
    11→/**
    12→ * Fetches all transactions for a user from the root transactions collection
    13→ * @param userId - The user ID
    14→ * @returns Array of transactions
    15→ */
    16→export async function getUserTransactions(
    17→  userId: string,
    18→): Promise<Transaction[]> {
    19→  try {
    20→    const transactionsRef = collection(db, 'transactions');
    21→    const q = query(
    22→      transactionsRef,
    23→      where('userId', '==', userId),
    24→      orderBy('date', 'desc'),
    25→    );
    26→    const querySnapshot: QuerySnapshot = await getDocs(q);
    27→
    28→    const transactions: Transaction[] = [];
    29→    querySnapshot.forEach((doc) => {
    30→      transactions.push({
    31→        ...(doc.data() as Transaction),
    32→      });
    33→    });
    34→
    35→    return transactions;
    36→  } catch (error) {
    37→    console.error('Error fetching user transactions:', error);
    38→    throw error;
    39→  }
    40→}
    41→
    42→/**
    43→ * Calculates investment summary statistics
    44→ * @param transactions - Array of transactions
    45→ * @returns Investment summary with total invested, returns, and count
    46→ */
    47→export function calculateInvestmentSummary(transactions: Transaction[]): {
    48→  totalInvested: number;
    49→  totalReturns: number;
    50→  totalInvestments: number;
    51→} {
    52→  let totalInvested = 0;
    53→  let totalReturns = 0;
    54→  const totalInvestments = transactions.filter(
    55→    (t) => t.type === 'investment',
    56→  ).length;
    57→
    58→  transactions.forEach((transaction) => {
    59→    if (transaction.type === 'investment') {
    60→      totalInvested += transaction.amount;
    61→    } else if (transaction.type === 'return') {
    62→      totalReturns += transaction.amount;
    63→    }
    64→  });
    65→
    66→  return {
    67→    totalInvested,
    68→    totalReturns,
    69→    totalInvestments,
    70→  };
    71→}
    72→
    73→/**
    74→ * Groups transactions by project and calculates position data
    75→ * @param transactions - Array of transactions
    76→ * @returns Array of positions with project data
    77→ */
    78→export function calculatePositions(transactions: Transaction[]): {
    79→  projectId: string;
    80→  projectName: string;
    81→  costBasis: number;
    82→  totalReturns: number;
    83→  transactions: Transaction[];
    84→  investmentDate: number;
    85→}[] {
    86→  const projectMap = new Map<
    87→    string,
    88→    {
    89→      projectName: string;
    90→      costBasis: number;
    91→      totalReturns: number;
    92→      transactions: Transaction[];
    93→      investmentDate: number;
    94→    }
    95→  >();
    96→
    97→  transactions.forEach((transaction) => {
    98→    const existing = projectMap.get(transaction.projectId);
    99→
   100→    if (existing) {
   101→      if (transaction.type === 'investment') {
   102→        existing.costBasis += transaction.amount;
   103→        // Keep the earliest investment date
   104→        if (transaction.date < existing.investmentDate) {
   105→          existing.investmentDate = transaction.date;
   106→        }
   107→      } else if (transaction.type === 'return') {
   108→        existing.totalReturns += transaction.amount;
   109→      }
   110→      existing.transactions.push(transaction);
   111→    } else {
   112→      projectMap.set(transaction.projectId, {
   113→        projectName: transaction.projectName,
   114→        costBasis: transaction.type === 'investment' ? transaction.amount : 0,
   115→        totalReturns: transaction.type === 'return' ? transaction.amount : 0,
   116→        transactions: [transaction],
   117→        investmentDate: transaction.date,
   118→      });
   119→    }
   120→  });
   121→
   122→  return Array.from(projectMap.entries())
   123→    .map(([projectId, data]) => ({
   124→      projectId,
   125→      ...data,
   126→    }))
   127→    .sort((a, b) => b.investmentDate - a.investmentDate);
   128→}
