     3→import { AuthAtoms } from '@modules/auth/jotai/atoms';
     4→import { Routes } from 'const/Routes';
     5→import { User, onAuthStateChanged } from 'firebase/auth';
     6→import { useSetAtom } from 'jotai';
     7→import { usePathname, useRouter } from 'next/navigation';
     8→import React, { createContext, useContext, useEffect, useState } from 'react';
     9→import { toast } from 'sonner';
    10→import { auth } from './config';
    11→import { getUserDocument } from './user-actions';
    12→
    13→interface AuthContextType {
    14→  user: User | null;
    15→  loading: boolean;
    16→  isAuthenticated: boolean;
    17→}
    18→
    19→const AuthContext = createContext<AuthContextType>({
    20→  user: null,
    21→  loading: true,
    22→  isAuthenticated: false,
    23→});
    24→
    25→export const useAuth = () => {
    26→  const context = useContext(AuthContext);
    27→  if (!context) {
    28→    throw new Error('useAuth must be used within an AuthProvider');
    29→  }
    30→  return context;
    31→};
    32→
    33→interface AuthProviderProps {
    34→  children: React.ReactNode;
    35→}
    36→
    37→// Auth pages that logged-in users should not access
    38→const AUTH_ROUTES = [Routes.LOGIN, Routes.SIGN_UP, Routes.RESET_PASSWORD];
    39→
    40→// Public routes that anyone can access
    41→const PUBLIC_ROUTES = [
    42→  Routes.HOME,
    43→  Routes.APPLY_HERE,
    44→  Routes.OVERVIEW,
    45→  Routes.FEES,
    46→  Routes.SUBMIT_PROJECT,
    47→  Routes.APPLY,
    48→  Routes.PRICING,
    49→  Routes.OUR_TEAM,
    50→  Routes.FAQ,
    51→  Routes.TERMS_OF_SERVICE,
    52→  Routes.PRIVACY_POLICY,
    53→  Routes.DISCLAIMER,
    54→];
    55→
    56→// Protected dashboard routes that require authentication
    57→const PROTECTED_ROUTES = [Routes.DASHBOARD];
    58→
    59→export function AuthProvider({ children }: AuthProviderProps) {
    60→  const [user, setUser] = useState<User | null>(null);
    61→  const [loading, setLoading] = useState(true);
    62→  const router = useRouter();
    63→  const pathname = usePathname();
    64→  const isInitialLoad = React.useRef(true);
    65→  const setFirestoreUser = useSetAtom(AuthAtoms.user);
    66→
    67→  useEffect(() => {
    68→    // Only run on client side
    69→    if (typeof window === 'undefined' || !auth) {
    70→      return;
    71→    }
    72→
    73→    // Set up authentication state listener
    74→    const unsubscribe = onAuthStateChanged(
    75→      auth,
    76→      async (firebaseUser) => {
    77→        setUser(firebaseUser);
    78→        setLoading(false);
    79→
    80→        // Check what type of route we're on
    81→        const isAuthRoute = AUTH_ROUTES.some((route) =>
    82→          pathname.startsWith(route),
    83→        );
    84→        const isPublicRoute = PUBLIC_ROUTES.some((route) =>
    85→          pathname === '/' ? pathname === route : pathname.startsWith(route),
    86→        );
    87→        const isProtectedRoute =
    88→          PROTECTED_ROUTES.some((route) => pathname.startsWith(route)) ||
    89→          (!isAuthRoute && !isPublicRoute);
    90→
    91→        if (firebaseUser) {
    92→          // User is logged in
    93→          console.log('User authenticated:', firebaseUser.email);
    94→
    95→          // Logged-in users cannot access auth pages (login, sign-up, reset-password)
    96→          if (isAuthRoute) {
    97→            // Show welcome toast only if this is not the initial load
    98→            if (!isInitialLoad.current) {
    99→              toast.success(
   100→                `Welcome back, ${firebaseUser.displayName || firebaseUser.email}!`,
   101→              );
   102→            }
   103→            router.push(Routes.DISCOVER_PROJECTS);
   104→          }
   105→
   106→          getUserDocument(firebaseUser.uid)
   107→            .then((user) => {
   108→              setFirestoreUser(user as FirestoreUser);
   109→            })
   110→            .catch((error) => {
   111→              console.error('Error fetching user document:', error);
   112→              toast.error('Error fetching user document');
   113→            });
   114→        } else {
   115→          // User is not logged in
   116→          console.log('User not authenticated');
   117→          setFirestoreUser(null);
   118→
   119→          // Non-logged-in users cannot access protected/dashboard routes
   120→          if (isProtectedRoute) {
   121→            // Show error toast only after initial load
   122→            if (!isInitialLoad.current) {
   123→              toast.error('Please log in to access this page');
   124→            }
   125→            router.push(Routes.LOGIN);
   126→          }
   127→          // Non-logged-in users can access public routes and auth routes - no action needed
   128→        }
   129→
   130→        // After first auth state change, we're no longer on initial load
   131→        isInitialLoad.current = false;
   132→        setLoading(false);
   133→      },
   134→      (error) => {
   135→        console.error('Auth state change error:', error);
   136→        setLoading(false);
   137→        isInitialLoad.current = false;
   138→        toast.error('Authentication error occurred');
   139→      },
   140→    );
   141→
   142→    // Cleanup subscription on unmount
   143→    return () => unsubscribe();
   144→  }, [pathname, router]);
   145→
   146→  const value = {
   147→    user,
   148→    loading,
   149→    isAuthenticated: !!user,
   150→  };
   151→
   152→  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
   153→}
